// Medical Reading Practice Test 4. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–3.
import {q, mix} from './q.js';
const CA='Crisis Averted (Rivers)', TB='Everything Is Tuberculosis (Green)', FR='Fragmented (Yurkiewicz)', NP='The Next Patient (Grant)', GR='Grit (Duckworth)';
const CDC='CDC', WHO='World Health Organization', AHRQ='Agency for Healthcare Research and Quality', DUCK='Duckworth et al., grit research publications', VAL='Valus Medical Reading lessons';

export default {
 id:'medical-reading-4',
 event:'Medical Reading',
 title:'Practice Test 4',
 subtitle:'Background and ideas behind the five assigned books',
 minutes:60,
 sources:'the five assigned books’ subject areas, with background from the CDC, WHO, AHRQ and published grit research (study the books for chapter details)',
 plan:[{area:CA,weight:20},{area:TB,weight:20},{area:FR,weight:20},{area:NP,weight:20},{area:GR,weight:20}],
 questions:mix([
  q(CA,'Tracking emergency visits for flu-like symptoms before lab results come back is called:','Syndromic surveillance',['Passive case reporting','Retrospective chart review','Vital records registration'],'A','It gives an early warning that something unusual may be spreading.',CDC),
  q(CA,'What does the WHO call a serious, unusual event that may spread internationally?','Public health emergency of international concern',['Seasonal health advisory of regional interest','Routine disease report for member states','Local outbreak watch for travelers only'],'B','The declaration triggers coordinated global recommendations under the International Health Regulations.',WHO),
  q(CA,'Vaccinating the contacts of each case, and then their contacts, is called:','Ring vaccination',['Mass vaccination','Routine vaccination','Seasonal vaccination'],'C','Ring vaccination helped eradicate smallpox and was used against Ebola.',WHO),
  q(CA,'How does vaccine efficacy differ from vaccine effectiveness?','Efficacy is from trials; effectiveness is real use',['Efficacy is always lower than effectiveness','They are measured in exactly the same way','Effectiveness is only measured in animals'],'D','Real-world results can differ because of age, timing and new variants.',CDC),
  q(CA,'Why does spread from people without symptoms make outbreaks harder to control?','Infected people do not know to isolate',['It makes vaccines stop working','It means the virus is not contagious','It only affects animals'],'A','Testing and masking in crowded places can help when symptoms are not a reliable guide.',CDC),
  q(CA,'Officials practice their outbreak response by talking through a pretend scenario. What is this?','Tabletop exercise',['Contact tracing','Case investigation','Field epidemiology'],'B','Exercises reveal gaps in plans before a real emergency happens.',CDC),
  q(CA,'Selected clinics report flu cases each week to represent a wider area. What is this?','Sentinel surveillance',['Passive surveillance','Census counting','Mass screening'],'C','Sentinel sites provide high-quality data without testing everyone.',CDC),
  q(CA,'When prevention works so well that people later say the threat was exaggerated, this is called the:','Prevention paradox',['Placebo effect','Survivor bias','Hawthorne effect'],'D','Success leaves no visible crisis, which can make future funding harder to win.',VAL),
  q(CA,'How does a mortality rate differ from a case fatality rate?','It uses the whole population, not just cases',['It counts only recovered patients','It is always higher than the CFR','It ignores all deaths in hospitals'],'A','Mortality rate shows deaths across a population, while CFR shows deaths among known cases.',CDC),
  q(CA,'Why must investigators set a case definition early in an outbreak?','So cases are counted consistently',['So no cases are ever counted','So only doctors can be cases','So the outbreak ends sooner'],'B','A case definition sets clear criteria for person, place, time and symptoms.',CDC),
  q(TB,'TB that spreads through the blood and forms many tiny lesions throughout the body is called:','Miliary TB',['Latent TB','Pleural TB','Primary TB'],'C','Its name comes from lesions that look like millet seeds on X-ray.',WHO),
  q(TB,'In the 1800s, how was consumption often viewed in art and literature?','As a romantic, artistic illness',['As a disease of only the rich','As a minor, harmless cold','As a sign of great strength'],'D','This image hid the real suffering and the role of poverty in TB.',VAL),
  q(TB,'Which short regimen of weekly doses for 3 months treats latent TB infection?','3HP (isoniazid and rifapentine)',['A single dose of penicillin','Two weeks of antiviral pills','Daily aspirin for one year'],'A','Shorter regimens improve completion, which helps prevent later TB disease.',CDC),
  q(TB,'What protection should health workers wear around patients with active TB?','A fitted N95 respirator',['A loose cloth mask','Sterile gloves only','A paper gown only'],'B','TB bacteria travel in tiny airborne droplets that surgical masks do not block well.',CDC),
  q(TB,'Why is TB often harder to diagnose in young children?','They rarely cough up sputum to test',['They never get TB at all','Their X-rays are always normal','TB tests cannot be used on children'],'C','Clinicians often rely on exposure history and symptoms in children.',WHO),
  q(TB,'Which chronic disease roughly triples a person’s risk of developing active TB?','Diabetes',['Asthma','Migraine','Acne'],'D','As diabetes rises worldwide, it adds to the global TB burden.',WHO),
  q(TB,'Why does stopping TB treatment early raise the risk of drug resistance?','Surviving bacteria can become resistant',['The drugs build up to toxic levels','The patient becomes immune','The bacteria all die at once'],'A','Completing every dose kills the bacteria before resistance develops.',CDC),
  q(TB,'Which building feature lowers TB spread in clinics and shelters?','Good ventilation and UV germicidal light',['Closing all windows tightly','Carpeting the waiting room floor','Turning off all fans and vents'],'B','Fresh air dilutes airborne bacteria, and UV light can kill them.',WHO),
  q(TB,'Newer all-oral regimens such as BPaL have shortened treatment for which patients?','Those with drug-resistant TB',['Those with latent TB only','Those with the common cold','Those with seasonal flu'],'C','Shorter, all-oral regimens replace long courses that once needed daily injections.',WHO),
  q(TB,'Why does stigma make TB harder to control?','People delay testing and treatment',['It speeds up recovery for patients','It makes the vaccine work better','It lowers the cost of medicines'],'D','Fear of rejection can keep people from seeking care or telling contacts.',WHO),
  q(FR,'Which federal initiative lets patients download their own health records?','Blue Button',['Red Flag Rule','Green Card','Gold Standard'],'A','Patients can then share records with new providers themselves.',AHRQ),
  q(FR,'Copying old notes forward in the electronic record can cause:','Outdated or wrong information',['Faster and better diagnoses','Smaller, clearer notes always','Fewer errors in every chart'],'B','Copy-paste can spread mistakes and hide what actually changed.',AHRQ),
  q(FR,'Clinicians ignoring frequent EHR warnings because most are not important is called:','Alert fatigue',['Burnout recovery','Shared decision making','Care coordination'],'C','Too many low-value alerts can cause truly important warnings to be missed.',AHRQ),
  q(FR,'Groups of providers who share savings for coordinated, high-quality care form a(n):','Accountable care organization',['Health savings account','Pharmacy benefit manager','Independent review board'],'D','ACOs reward providers for working together rather than for the number of services.',AHRQ),
  q(FR,'Why can fee-for-service payment add to fragmentation?','It pays for visits, not coordination',['It pays only for coordinated care','It bans specialist referrals','It requires a single doctor'],'A','Time spent calling other clinicians or teaching patients is often unpaid.',AHRQ),
  q(FR,'Which team member often arranges home services and equipment before discharge?','Social worker or case manager',['Hospital parking attendant','Dietary aide on the unit','Laboratory courier staff'],'B','Discharge planning helps prevent dangerous gaps in care when patients leave the hospital for home.',AHRQ),
  q(FR,'When care is fragmented, who often ends up coordinating it?','Patients and family caregivers',['Insurance company call centers','Hospital parking staff','Medical device makers'],'C','Caregivers may carry records, track appointments and relay information.',AHRQ),
  q(FR,'Which part of the EHR lists a patient’s current diagnoses for all clinicians to see?','Problem list',['Billing ledger','Visitor log','Staff roster'],'D','An accurate, updated problem list helps every provider see the full picture.',AHRQ),
  q(FR,'Which movement lets patients read the notes clinicians write about them?','OpenNotes',['Closed charts','Locked files','Sealed records'],'A','Reading notes can help patients catch errors and follow their care plan.',AHRQ),
  q(FR,'Which document gives patients a summary of their visit and next steps?','After-visit summary',['Operative report','Pathology report','Incident report'],'B','Clear summaries help patients follow plans between appointments.',AHRQ),
  q(NP,'Which measure shows how much a test result changes the odds of disease?','Likelihood ratio',['Response rate','Mortality ratio','Body mass index'],'C','Large likelihood ratios strongly shift the probability of a diagnosis.',AHRQ),
  q(NP,'A clinician looks only for evidence that supports their first idea. Which bias is this?','Confirmation bias',['Availability bias','Hindsight bias','Framing effect'],'D','Actively seeking evidence against a diagnosis helps counter this bias.',AHRQ),
  q(NP,'A clinician stops looking after finding one fracture and misses a second. What is this?','Search satisficing',['Anchoring bias','Overconfidence bias','Outcome bias'],'A','A systematic review of the whole image helps catch additional findings.',AHRQ),
  q(NP,'Feelings about a patient influence a clinician’s judgment. Which bias is this?','Affective bias',['Base rate neglect','Framing effect','Search satisficing'],'B','Noticing strong feelings is a cue to slow down and recheck reasoning.',AHRQ),
  q(NP,'Why do many EDs use checklists for high-risk complaints such as chest pain?','To reduce missed steps',['To slow all patient care','To replace all clinicians','To raise hospital bills'],'C','Checklists support memory during busy, high-pressure shifts so key steps are not skipped.',AHRQ),
  q(NP,'Deciding whether an ED patient will be admitted, transferred or sent home is called:','Disposition',['Triage','Intubation','Registration'],'D','Disposition decisions balance safety, resources and the patient’s needs.',AHRQ),
  q(NP,'Before sending a patient home, an ED clinician explains when to come back. What are these?','Return precautions',['Billing instructions','Visitor rules','Parking directions'],'A','Clear warning signs give patients a safety net if their condition changes.',AHRQ),
  q(NP,'A patient stays in the hospital for testing without being formally admitted. What is this status?','Observation status',['Inpatient admission','Outpatient surgery','Hospice care'],'B','Observation status can affect what insurance, including Medicare, will pay.',AHRQ),
  q(NP,'Why are high rates of burnout among emergency physicians a patient safety concern?','Burnout is linked to more errors',['Burnout improves focus and care','Burnout shortens patient waits','Burnout has no effect on care'],'C','Supporting clinician well-being is part of keeping patients safe.',AHRQ),
  q(NP,'Patients who visit the ED very often frequently have unmet needs such as:','Housing, food and mental health care',['Too many primary care visits','Excess health insurance plans','Too much access to clinics'],'D','Connecting them with social services can improve health and reduce visits.',AHRQ),
  q(GR,'Complete absorption in a challenging task that feels effortless is called:','Flow',['Rumination','Burnout','Boredom'],'A','Duckworth notes that experts experience flow during performance more than practice.',DUCK),
  q(GR,'Students who aim to learn and improve, not just to look smart, hold which goals?','Mastery goals',['Performance-avoid goals','Social comparison goals','Fixed ability goals'],'B','Mastery goals are linked to persistence after setbacks because mistakes are seen as part of learning.',DUCK),
  q(GR,'Calling an old idea by a new name and treating it as new is called the:','Jangle fallacy',['Gambler’s fallacy','Straw man fallacy','Sunk cost fallacy'],'C','Critics argue grit may partly repackage the older trait of conscientiousness.',DUCK),
  q(GR,'West Point cadets were already highly selected. Which research issue does this raise?','Restriction of range',['Random assignment','Double blinding','Placebo control'],'D','When everyone is similar on talent, other traits can look more predictive.',DUCK),
  q(GR,'Grit measured for a specific activity, such as math, rather than life in general is:','Domain-specific grit',['General intelligence','Random chance','Physical endurance'],'A','Some studies find domain-specific measures predict outcomes in that area better.',DUCK),
  q(GR,'According to Duckworth, grit is more about which quality than intensity?','Stamina over time',['Short bursts of effort','Natural talent alone','Fast early success'],'B','Grit means staying committed to the same top-level goal for years.',DUCK),
  q(GR,'In Duckworth’s goal hierarchy, what should a gritty person do with a low-level goal that fails?','Swap it for another route',['Abandon the top goal','Repeat it forever unchanged','Hide the failure from others'],'C','Flexibility at lower levels helps protect the long-term ultimate goal.',DUCK),
  q(GR,'Belief in one’s ability to succeed at a specific task is called:','Self-efficacy',['Self-esteem','Self-control','Self-awareness'],'D','Albert Bandura showed that self-efficacy shapes effort and persistence.',DUCK),
  q(GR,'Which classic study tested children’s ability to wait for a larger reward?','The marshmallow test',['The Stanford prison study','The Milgram study','The Hawthorne study'],'A','Later replications found the link to life outcomes was smaller than first reported.',DUCK),
  q(GR,'Which nonprofit did Duckworth co-found to apply character research in schools?','Character Lab',['Teach for All','Khan Academy','Code.org'],'B','It shares research-based tips on strengths such as grit, curiosity and gratitude.',DUCK)
 ],8940)
};
